sp_widget.client_script:
api.controller = function() {

  /* =========================================================
     GATENOW · REVIEWER OVERVIEW · Client script

     Chart geometry only. Every figure on this page is counted
     on the server; the controller turns counts into heights,
     which is the one thing that has to know how tall the plot
     is.

     The helper names match the applicant Overview deliberately
     — pct, pipeH, monthH, healthPct, spark — so the two
     dashboards can be read side by side without translating
     between them.

     Nothing here writes to window.location or calls
     window.open: every destination on the page is an anchor
     with an href.
     ========================================================= */

  var c = this;


  /* =====================================================
     ARITHMETIC
     ===================================================== */

  c.pct = function(n, total) {
    if (!total) return 0;
    return Math.round((n / total) * 100);
  };

  /* an axis that runs to a round number above the tallest bar.
     Ending the axis exactly at the peak leaves the tallest bar
     touching the top rule, which reads as clipped. */
  function ceilTo(peak) {
    if (peak <= 4)  return 4;
    if (peak <= 10) return Math.ceil(peak / 2) * 2;
    if (peak <= 50) return Math.ceil(peak / 5) * 5;
    return Math.ceil(peak / 10) * 10;
  }

  function axisFor(top) {
    /* five labels, high to low, whole numbers only — a count of
       reviews has no half and a tick reading 2.5 is a tick
       nobody can use */
    var step = top / 4;
    var out  = [];
    for (var i = 4; i >= 0; i--) out.push(Math.round(step * i));
    return out;
  }


  /* =====================================================
     THE PIPELINE CHART
     ===================================================== */

  var pipePeak = 0;
  var pipe = (c.data.pipeline || []);

  for (var i = 0; i < pipe.length; i++) {
    if (pipe[i].count > pipePeak) pipePeak = pipe[i].count;
  }

  var pipeTop = ceilTo(pipePeak);

  c.pipeAxis = axisFor(pipeTop);

  c.pipeH = function(n) {
    if (!pipeTop) return 0;
    /* a zero bar still draws a sliver. A column that vanishes
       entirely reads as missing data rather than as none. */
    return n === 0 ? 1.5 : Math.max(3, Math.round((n / pipeTop) * 100));
  };


  /* =====================================================
     THE MONTHLY CHART
     ===================================================== */

  var monthPeak = 0;
  var months = ((c.data.monthly || {}).months || []);

  for (var m = 0; m < months.length; m++) {
    if (months[m].done > monthPeak)     monthPeak = months[m].done;
    if (months[m].progress > monthPeak) monthPeak = months[m].progress;
    if (months[m].pending > monthPeak)  monthPeak = months[m].pending;
  }

  var monthTop = ceilTo(monthPeak);

  c.monthAxis = axisFor(monthTop);

  c.monthH = function(n) {
    if (!monthTop) return 0;
    return n === 0 ? 1.5 : Math.max(3, Math.round((n / monthTop) * 100));
  };


  /* =====================================================
     THE KPI VISUALS
     ===================================================== */

  /* Completed per month, drawn as the applicant Overview draws
     its milestone bars. Scaled to its own peak, because the
     shape of the run is the point rather than the absolute
     height. */
  c.monthlyH = function(n, series) {
    var peak = 0;
    for (var k = 0; k < (series || []).length; k++) {
      if (series[k] > peak) peak = series[k];
    }
    if (!peak) return 30;
    return Math.max(30, Math.round((n / peak) * 100));
  };

  /* the score distribution, on the same 1 to 10 grid the
     scoring control uses */
  var distPeak = 0;
  var dist = ((c.data.kpi || {}).score || {}).dist || [];

  for (var d = 0; d < dist.length; d++) {
    if (dist[d] > distPeak) distPeak = dist[d];
  }

  c.distH = function(n) {
    if (!distPeak) return 8;
    return n === 0 ? 8 : Math.max(18, Math.round((n / distPeak) * 100));
  };

  /* the same 7 and 4 thresholds the scoring control uses, so
     no two screens disagree about what a 7 means */
  c.bandOf = function(n) {
    if (n >= 7) return 'high';
    if (n >= 4) return 'mid';
    return 'low';
  };

  /* the three segments of the due-date bar */
  c.duePct = function(n) {
    var w = c.data.kpi.waiting;
    var total = (w.overdue || 0) + (w.thisWeek || 0) + (w.later || 0);
    if (!total) return n === 0 ? 0 : 100;
    return Math.round((n / total) * 100);
  };

  c.healthPct = function(tone) {
    var h = c.data.health || {};
    var total = (h.red || 0) + (h.yellow || 0) + (h.green || 0);
    if (!total) return 0;
    return Math.round(((h[tone] || 0) / total) * 100);
  };


  /* =====================================================
     THE SPARKLINE

     Built the way the applicant Overview builds its own: a
     polyline and a filled polygon across a 100 by 34 viewBox,
     plus the vertical position of the end dot as a percentage.

     The scale is fitted to the series because a cumulative
     count has no natural ceiling — unlike a score, which is
     always out of ten and is therefore never fitted.
     ===================================================== */

  function spark(values) {

    var v = values || [];

    if (!v.length) {
      return { line: '0,17 100,17', area: '0,34 0,17 100,17 100,34', dotTop: 50 };
    }

    var peak = 0;
    for (var i = 0; i < v.length; i++) {
      if (v[i] > peak) peak = v[i];
    }
    if (!peak) peak = 1;

    /* 3 and 31 rather than 0 and 34: a line that touches the
       edge of its own box looks clipped, and the end dot is
       drawn outside the svg */
    var pts  = [];
    var last = 17;

    for (var j = 0; j < v.length; j++) {
      var x = v.length === 1 ? 100 : Math.round((j / (v.length - 1)) * 100);
      var y = Math.round(31 - (v[j] / peak) * 28);
      pts.push(x + ',' + y);
      last = y;
    }

    return {
      line  : pts.join(' '),
      area  : '0,34 ' + pts.join(' ') + ' 100,34',
      dotTop: Math.round((last / 34) * 100)
    };
  }

  c.sparkAssigned = spark(((c.data.kpi || {}).assigned || {}).cumulative);
};

sp_widget.css:
/* =========================================================
   GATENOW · REVIEWER OVERVIEW
   Service Portal widget · CSS / SCSS

   Written with fully expanded selectors on purpose.
   The Service Portal Sass compiler does not support parent
   selector concatenation (&__head, &--green), so every rule
   below is written out in full.

   ── RELATIONSHIP TO THE APPLICANT OVERVIEW ────────────────

   The token block and every shared component below are the
   applicant Overview's, unchanged: same Poppins, same indigo,
   same 16px radius, same two-layer shadow, same gn-kpi,
   gn-card, gn-chart and gn-table anatomy.

   Service Portal injects each widget's CSS into the page it
   renders on, so two widgets on two different pages each need
   their own copy. Copying rather than approximating is the
   point: a reviewer who also applies meets identical controls,
   and any change to the shared system is a search-and-replace
   across two files rather than a redesign.

   Reviewer-only additions are gathered at the end under their
   own heading, and there are four of them.

   ── APPLE'S THREE, APPLIED ────────────────────────────────

   Deference. The chrome recedes and the data carries the
   weight. No new accent colour, no new border, no ornament
   that does not encode something.

   Clarity. One meaning per colour and it holds across every
   screen in the portal: indigo is volume, green is settled,
   amber is due soon, red is overdue. Figures are tabular so
   digits line up down a column. Negative space does the
   grouping that a box would otherwise have to.

   Depth. The existing two-layer shadow is the only layering
   on the page. Nothing new floats, and the one element that
   rises on hover is the chart tooltip, because it is the one
   element that is genuinely above the page.
   ========================================================= */

$gn-bg:          #f4f6fb;
$gn-card:        #ffffff;
$gn-line:        #e7eaf2;
$gn-line-soft:   #eff2f7;

$gn-ink:         #16203a;
$gn-ink-2:       #3f4a63;
$gn-muted:       #7b8598;
$gn-muted-2:     #9aa3b4;

$gn-indigo:      #4457c9;
$gn-indigo-dk:   #3a4bb3;
$gn-indigo-mid:  #7b90ee;
$gn-indigo-soft: #aebcf5;
$gn-violet:      #6f5fd0;
$gn-green:       #1f9d6d;
$gn-sage:        #93c8ae;
$gn-amber:       #e2a233;
$gn-red:         #e0525f;
$gn-slate:       #c9d2e3;

$gn-font: "Poppins", "Inter", "Segoe UI", -apple-system, BlinkMacSystemFont, Arial, sans-serif;


/* =========================================================
   SHELL
   ========================================================= */

/* Service Portal wraps every widget in a panel that clips
   anything leaving its box, which cuts the rail tooltips off
   at the column edge. */
.panel,
.panel-body,
.sp-widget { overflow: visible !important; }

.gn-layout.gn-p-overview {
  display: flex;
  align-items: stretch;
  min-height: 100vh;
  overflow: visible !important;
}

.gn-p-overview .aw-sidebar {
  flex: 0 0 auto;
  position: sticky;
  top: 0;
  height: 100vh;
  z-index: 10;
  overflow: visible;
}

/* Without min-width: 0 a flex child refuses to shrink below
   its own content width, and slides under the rail rather
   than narrowing. */
.gn-p-overview .gn-dash {
  flex: 1;
  min-width: 0;
  overflow: visible;
  background: $gn-bg;
  font-family: $gn-font;
  color: $gn-ink;
  padding: 26px 30px 46px;
  min-height: 100vh;
}

.gn-p-overview .gn-dash *,
.gn-p-overview .gn-dash *::before,
.gn-p-overview .gn-dash *::after { box-sizing: border-box; }

.gn-p-overview .gn-dash h1,
.gn-p-overview .gn-dash h2,
.gn-p-overview .gn-dash p { margin: 0; }

.gn-p-overview .gn-dash a { text-decoration: none; }
.gn-p-overview .gn-dash a:hover,
.gn-p-overview .gn-dash a:focus { text-decoration: none; }

.gn-p-overview .gn-dash :focus-visible {
  outline: 2px solid $gn-indigo;
  outline-offset: 2px;
}


/* =========================================================
   HEADER
   ========================================================= */

.gn-p-overview .gn-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 22px;
}

.gn-p-overview .gn-head__left { min-width: 0; }

.gn-p-overview .gn-head__title {
  font-size: 30px;
  font-weight: 600;
  letter-spacing: -0.6px;
  line-height: 1.15;
  color: $gn-ink;
}

.gn-p-overview .gn-head__meta {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 6px;
  font-size: 12.5px;
  color: $gn-muted;
}

.gn-p-overview .gn-head__right {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-shrink: 0;
}

.gn-p-overview .gn-live {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: $gn-green;
  flex-shrink: 0;
}

.gn-p-overview .gn-avatar {
  width: 44px;
  height: 44px;
  border-radius: 12px;
  background: $gn-indigo;
  color: #ffffff;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.3px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}


/* =========================================================
   KPI CARDS
   ========================================================= */

.gn-p-overview .gn-kpis {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 20px;
  margin-bottom: 20px;
}

/* Portal columns are narrower than the viewport, so the grid
   also reflows on its own container width, not just on media
   queries. */
@supports (grid-template-columns: repeat(auto-fit, minmax(220px, 1fr))) {
  .gn-p-overview .gn-kpis { grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); }
}

.gn-p-overview .gn-kpi {
  display: flex;
  flex-direction: column;
  background: $gn-card;
  border: 1px solid $gn-line;
  border-radius: 16px;
  padding: 20px 22px 16px;
  min-height: 212px;
  box-shadow: 0 1px 2px rgba(22, 32, 58, 0.04), 0 8px 20px rgba(22, 32, 58, 0.04);
}

.gn-p-overview .gn-kpi__top {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.gn-p-overview .gn-kpi__label {
  font-size: 11.5px;
  font-weight: 600;
  letter-spacing: 0.8px;
  text-transform: uppercase;
  color: $gn-muted;
}

.gn-p-overview .gn-kpi__icon {
  width: 32px;
  height: 32px;
  border-radius: 9px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 13px;
  flex-shrink: 0;
}

.gn-p-overview .gn-kpi__icon--indigo { color: $gn-indigo; background: #edf1ff; }
.gn-p-overview .gn-kpi__icon--violet { color: $gn-violet; background: #f0edfd; }
.gn-p-overview .gn-kpi__icon--amber { color: #c98a1c;    background: #fdf4e2; }

.gn-p-overview .gn-kpi__figure {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  margin-top: 14px;
}

.gn-p-overview .gn-kpi__value {
  font-size: 38px;
  font-weight: 600;
  line-height: 1;
  letter-spacing: -1.4px;
  color: $gn-ink;
}

.gn-p-overview .gn-kpi__desc {
  margin-top: 10px;
  font-size: 12.5px;
  line-height: 1.55;
  color: $gn-muted;
}

.gn-p-overview .gn-kpi__caption {
  margin-top: auto;
  padding-top: 10px;
  font-size: 11px;
  color: $gn-muted-2;
}


/* ---------- chips ---------- */

.gn-p-overview .gn-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 4px 10px;
  border-radius: 999px;
  font-size: 11.5px;
  font-weight: 500;
  white-space: nowrap;
  background: #f1f3f8;
  color: $gn-ink-2;
}

.gn-p-overview .gn-chip--green { background: #e6f6ef; color: #178a5e; }
.gn-p-overview .gn-chip--amber { background: #fdf1dd; color: #b9801a; }
.gn-p-overview .gn-chip--red { background: #fdecee; color: #cf4351; }


/* ---------- sparkline ---------- */

.gn-p-overview .gn-spark {
  position: relative;
  height: 34px;
  margin-top: 16px;
}

.gn-p-overview .gn-spark svg {
  width: 100%;
  height: 100%;
  display: block;
  overflow: visible;
}

.gn-p-overview .gn-spark__line {
  fill: none;
  stroke-width: 2;
  stroke-linejoin: round;
  stroke-linecap: round;
  vector-effect: non-scaling-stroke;
}

.gn-p-overview .gn-spark__area {
  stroke: none;
  fill: rgba(68, 87, 201, 0.10);
}

.gn-p-overview .gn-spark__dot {
  position: absolute;
  right: 0;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  transform: translate(1px, -50%);
  background: $gn-indigo;
}

.gn-p-overview .gn-spark--indigo .gn-spark__line { stroke: $gn-indigo; }
.gn-p-overview .gn-spark--indigo .gn-spark__area { fill: rgba(68, 87, 201, 0.10); }
.gn-p-overview .gn-spark--indigo .gn-spark__dot { background: $gn-indigo; }

.gn-p-overview .gn-spark--green .gn-spark__line { stroke: $gn-green; }
.gn-p-overview .gn-spark--green .gn-spark__area { fill: rgba(31, 157, 109, 0.12); }
.gn-p-overview .gn-spark--green .gn-spark__dot { background: $gn-green; }


/* ---------- milestone bars ---------- */

.gn-p-overview .gn-milestones {
  display: flex;
  align-items: flex-end;
  gap: 5px;
  height: 34px;
  margin-top: 16px;
}

.gn-p-overview .gn-milestone {
  flex: 1;
  min-height: 30%;
  border-radius: 4px;
  background: #dde3f5;
  transition: height 0.4s ease;
}

.gn-p-overview .gn-milestone.is-current { background: $gn-indigo; }


/* ---------- segmented bar ---------- */

.gn-p-overview .gn-segbar {
  display: flex;
  height: 7px;
  margin-top: 22px;
  border-radius: 999px;
  overflow: hidden;
  background: #e9edf4;
}

.gn-p-overview .gn-seg { height: 100%; transition: width 0.4s ease; }
.gn-p-overview .gn-seg--red { background: $gn-red; }
.gn-p-overview .gn-seg--amber { background: $gn-amber; }
.gn-p-overview .gn-seg--grey { background: #dfe4ee; }


/* =========================================================
   CARD SYSTEM
   ========================================================= */

.gn-p-overview .gn-row {
  display: grid;
  gap: 20px;
  margin-bottom: 20px;
}

.gn-p-overview .gn-row--wide {
  grid-template-columns: minmax(0, 1.5fr) minmax(0, 1fr);
}

.gn-p-overview .gn-card {
  display: flex;
  flex-direction: column;
  background: $gn-card;
  border: 1px solid $gn-line;
  border-radius: 16px;
  box-shadow: 0 1px 2px rgba(22, 32, 58, 0.04), 0 8px 20px rgba(22, 32, 58, 0.04);
  min-width: 0;
  overflow: hidden;
}

.gn-p-overview .gn-card__head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding: 20px 24px 4px;
}

.gn-p-overview .gn-card__head h2 {
  font-size: 17px;
  font-weight: 600;
  letter-spacing: -0.2px;
  line-height: 1.3;
  color: $gn-ink;
}

.gn-p-overview .gn-card__head p {
  margin-top: 4px;
  font-size: 12.5px;
  color: $gn-muted;
}

.gn-p-overview .gn-card__body {
  padding: 18px 24px 22px;
  flex: 1;
}

.gn-p-overview .gn-card__body--tight { padding: 12px 16px 16px; }

.gn-p-overview .gn-card__foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin: 0 24px;
  padding: 14px 0 18px;
  border-top: 1px solid $gn-line-soft;
  font-size: 12px;
  color: $gn-muted;
}

.gn-p-overview .gn-link {
  color: $gn-indigo;
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
}

.gn-p-overview .gn-link:hover { color: $gn-indigo-dk; }

.gn-p-overview .gn-note {
  padding-top: 16px;
  margin-top: 16px;
  border-top: 1px solid $gn-line-soft;
  font-size: 12px;
  line-height: 1.5;
  color: $gn-muted-2;
}

.gn-p-overview .gn-empty {
  padding: 34px 12px;
  text-align: center;
  font-size: 12.5px;
  line-height: 1.6;
  color: $gn-muted-2;
}

.gn-p-overview .gn-total {
  text-align: right;
  flex-shrink: 0;
}

.gn-p-overview .gn-total strong {
  display: block;
  font-size: 21px;
  font-weight: 600;
  letter-spacing: -0.5px;
  color: $gn-ink;
}

.gn-p-overview .gn-total span {
  font-size: 11px;
  color: $gn-muted-2;
}


/* =========================================================
   CHARTS
   ========================================================= */

.gn-p-overview .gn-chart {
  display: flex;
  gap: 12px;
}

.gn-p-overview .gn-chart__axis {
  width: 22px;
  height: 220px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  align-items: flex-end;
  font-size: 11px;
  line-height: 1;
  color: $gn-muted-2;
  flex-shrink: 0;
}

.gn-p-overview .gn-chart__plot {
  position: relative;
  flex: 1;
  height: 220px;
  min-width: 0;
}

.gn-p-overview .gn-grid {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.gn-p-overview .gn-grid__line {
  display: block;
  width: 100%;
  height: 1px;
  background: $gn-line-soft;
}

.gn-p-overview .gn-grid__line:last-child { background: $gn-line; }

.gn-p-overview .gn-cols {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  display: flex;
  align-items: flex-end;
  justify-content: space-around;
  gap: 10px;
}

.gn-p-overview .gn-col {
  position: relative;
  flex: 1;
  min-width: 0;
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-end;
}

.gn-p-overview .gn-col__track {
  width: 62px;
  max-width: 72%;
  flex: 1;
  display: flex;
  align-items: flex-end;
}

.gn-p-overview .gn-col__bar {
  position: relative;
  width: 100%;
  min-height: 3px;
  border-radius: 6px 6px 0 0;
  background: $gn-indigo-soft;
  transition: height 0.45s ease;
}

.gn-p-overview .gn-col__value {
  position: absolute;
  bottom: 100%;
  left: 0;
  right: 0;
  margin-bottom: 7px;
  text-align: center;
  font-size: 12px;
  font-weight: 600;
  color: $gn-ink-2;
}

.gn-p-overview .gn-col__cluster {
  display: flex;
  align-items: flex-end;
  justify-content: center;
  gap: 5px;
  width: 100%;
  height: 100%;
}

.gn-p-overview .gn-gbar {
  width: 14px;
  min-height: 2px;
  border-radius: 4px 4px 0 0;
  transition: height 0.45s ease;
}

.gn-p-overview .gn-gbar--indigo { background: $gn-indigo; }
.gn-p-overview .gn-gbar--periwinkle { background: $gn-indigo-mid; }
.gn-p-overview .gn-gbar--sage { background: $gn-sage; }

.gn-p-overview .gn-tip {
  position: absolute;
  bottom: 100%;
  left: 50%;
  transform: translate(-50%, 2px);
  min-width: 150px;
  padding: 8px 11px;
  border-radius: 9px;
  background: $gn-ink;
  color: #ffffff;
  font-size: 11px;
  line-height: 1.5;
  text-align: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.18s ease, transform 0.18s ease;
  z-index: 5;
}

.gn-p-overview .gn-tip strong {
  display: block;
  font-weight: 600;
}

.gn-p-overview .gn-col:hover .gn-tip {
  opacity: 1;
  transform: translate(-50%, -6px);
}

.gn-p-overview .gn-labels {
  display: flex;
  justify-content: space-around;
  gap: 10px;
  padding-left: 34px;
  margin-top: 10px;
}

.gn-p-overview .gn-labels span {
  flex: 1;
  text-align: center;
  font-size: 12px;
  color: $gn-ink-2;
}

.gn-p-overview .gn-keys {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 16px;
  max-width: 300px;
  font-size: 12px;
  color: $gn-ink-2;
}

.gn-p-overview .gn-keys span {
  display: inline-flex;
  align-items: center;
  gap: 7px;
}

.gn-p-overview .gn-key {
  width: 9px;
  height: 9px;
  border-radius: 3px;
  flex-shrink: 0;
}

.gn-p-overview .gn-key--indigo { background: $gn-indigo; }
.gn-p-overview .gn-key--periwinkle { background: $gn-indigo-mid; }
.gn-p-overview .gn-key--sage { background: $gn-sage; }


/* =========================================================
   HEALTH AND LISTS
   ========================================================= */

.gn-p-overview .gn-health {
  display: flex;
  height: 46px;
  border-radius: 12px;
  overflow: hidden;
  background: #eef1f6;
  color: #ffffff;
  font-size: 13px;
  font-weight: 500;
}

.gn-p-overview .gn-health__seg {
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 42px;
  white-space: nowrap;
  transition: width 0.45s ease;
}

.gn-p-overview .gn-health__seg--green { background: #1f9d6d; }
.gn-p-overview .gn-health__seg--amber { background: #dfa227; }
.gn-p-overview .gn-health__seg--red { background: $gn-red; }

.gn-p-overview .gn-health__rest {
  flex: 1;
  min-width: 52px;
  padding: 0 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: $gn-muted;
  font-size: 12.5px;
}

.gn-p-overview .gn-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 14px;
  padding-bottom: 18px;
  border-bottom: 1px solid $gn-line-soft;
}

.gn-p-overview .gn-legend__pill {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 5px 11px;
  border-radius: 999px;
  background: #f4f6fa;
  font-size: 12px;
  color: $gn-ink-2;
}

.gn-p-overview .gn-dot {
  display: inline-block;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  flex-shrink: 0;
  background: $gn-slate;
}

.gn-p-overview .gn-dot--green { background: $gn-green; }
.gn-p-overview .gn-dot--amber { background: $gn-amber; }
.gn-p-overview .gn-dot--red { background: $gn-red; }

.gn-p-overview .gn-projects { padding-top: 6px; }

.gn-p-overview .gn-project {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 6px 12px;
  padding: 14px 0 10px;
  border-bottom: 1px solid $gn-line-soft;
}

.gn-p-overview .gn-project:last-child { border-bottom: 0; }

.gn-p-overview .gn-project__name {
  display: flex;
  align-items: center;
  gap: 9px;
  min-width: 0;
  font-size: 13.5px;
  font-weight: 500;
  color: $gn-ink;
}

.gn-p-overview .gn-project__name span {
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.gn-p-overview .gn-project__pct {
  font-size: 13px;
  color: $gn-ink-2;
  white-space: nowrap;
}

.gn-p-overview .gn-project__track {
  grid-column: 1 / -1;
  height: 5px;
  border-radius: 999px;
  background: #edf0f6;
  overflow: hidden;
}

.gn-p-overview .gn-project__fill {
  height: 100%;
  border-radius: 999px;
  background: $gn-slate;
  transition: width 0.45s ease;
}

.gn-p-overview .gn-project__fill--green { background: $gn-green; }
.gn-p-overview .gn-project__fill--amber { background: $gn-amber; }
.gn-p-overview .gn-project__fill--red { background: $gn-red; }


/* =========================================================
   CLAIM BARS
   ========================================================= */

.gn-p-overview .gn-claim { margin-bottom: 18px; }
.gn-p-overview .gn-claim:last-child { margin-bottom: 0; }

.gn-p-overview .gn-claim__meta {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 8px;
}

.gn-p-overview .gn-claim__label {
  font-size: 13.5px;
  font-weight: 500;
  color: $gn-ink;
}

.gn-p-overview .gn-claim__value {
  font-size: 12.5px;
  color: $gn-muted;
}

.gn-p-overview .gn-claim__track {
  height: 8px;
  border-radius: 999px;
  background: #edf0f6;
  overflow: hidden;
}

.gn-p-overview .gn-claim__fill {
  height: 100%;
  border-radius: 999px;
  background: $gn-indigo-soft;
  transition: width 0.45s ease;
}

.gn-p-overview .gn-claim__fill--green { background: $gn-green; }
.gn-p-overview .gn-claim__fill--indigo { background: $gn-indigo; }
.gn-p-overview .gn-claim__fill--periwinkle { background: $gn-indigo-mid; }
.gn-p-overview .gn-claim__fill--soft { background: $gn-indigo-soft; }
.gn-p-overview .gn-claim__fill--amber { background: $gn-amber; }
.gn-p-overview .gn-claim__fill--red { background: $gn-red; }


/* =========================================================
   TABLE
   ========================================================= */

.gn-p-overview .gn-table {
  width: 100%;
  margin-top: 14px;
}

.gn-p-overview .gn-table__head,
.gn-p-overview .gn-table__row {
  display: grid;
  grid-template-columns: 1.1fr 1.2fr 1.4fr 1.1fr 1.2fr 0.85fr;
  align-items: center;
  gap: 12px;
  padding: 0 24px;
}

.gn-p-overview .gn-table__head {
  height: 40px;
  background: #f7f9fc;
  border-top: 1px solid $gn-line-soft;
  border-bottom: 1px solid $gn-line-soft;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.7px;
  text-transform: uppercase;
  color: $gn-muted;
}

.gn-p-overview .gn-table__row {
  min-height: 66px;
  padding-top: 12px;
  padding-bottom: 12px;
  border-bottom: 1px solid $gn-line-soft;
}

.gn-p-overview .gn-table__row:last-child { border-bottom: 0; }
.gn-p-overview .gn-table__row:hover { background: #fafbfe; }

.gn-p-overview .gn-cell {
  font-size: 13px;
  min-width: 0;
}

.gn-p-overview .gn-cell--name {
  font-weight: 500;
  color: $gn-ink;
  line-height: 1.4;
}

.gn-p-overview .gn-cell--related {
  color: $gn-indigo;
  line-height: 1.4;
}

.gn-p-overview .gn-cell--date {
  color: $gn-ink-2;
  line-height: 1.4;
}

.gn-p-overview .gn-tag {
  display: inline-flex;
  padding: 4px 9px;
  border-radius: 7px;
  background: #edf1ff;
  color: $gn-indigo;
  font-size: 11.5px;
  font-weight: 500;
  white-space: nowrap;
}

.gn-p-overview .gn-state {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 10px;
  border-radius: 999px;
  background: #f2f4f8;
  color: $gn-ink-2;
  font-size: 11.5px;
  font-weight: 500;
  white-space: nowrap;
}

.gn-p-overview .gn-state--red { background: #fdecee; color: #cf4351; }
.gn-p-overview .gn-state--amber { background: #fdf3e0; color: #b9801a; }
.gn-p-overview .gn-state--green { background: #e6f6ef; color: #178a5e; }
.gn-p-overview .gn-state--grey { background: #f2f4f8; color: $gn-muted; }

.gn-p-overview .gn-state--red .gn-dot { background: $gn-red; }
.gn-p-overview .gn-state--amber .gn-dot { background: $gn-amber; }
.gn-p-overview .gn-state--green .gn-dot { background: $gn-green; }
.gn-p-overview .gn-state--grey .gn-dot { background: $gn-muted-2; }

.gn-p-overview .gn-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 74px;
  height: 34px;
  padding: 0 14px;
  border: 1px solid $gn-line;
  border-radius: 9px;
  background: $gn-card;
  color: $gn-ink-2;
  font-size: 12.5px;
  font-weight: 500;
}

.gn-p-overview .gn-btn:hover {
  border-color: $gn-indigo-soft;
  color: $gn-indigo;
}

.gn-p-overview .gn-btn--primary {
  background: $gn-indigo;
  border-color: $gn-indigo;
  color: #ffffff;
}

.gn-p-overview .gn-btn--primary:hover {
  background: $gn-indigo-dk;
  border-color: $gn-indigo-dk;
  color: #ffffff;
}


/* =========================================================
   PROGRAM CARDS
   ========================================================= */

.gn-p-overview .gn-program {
  display: block;
  padding: 16px 18px;
  margin-bottom: 12px;
  border: 1px solid $gn-line;
  border-radius: 12px;
  color: inherit;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.gn-p-overview .gn-program:last-child { margin-bottom: 0; }

.gn-p-overview .gn-program:hover {
  border-color: $gn-indigo-soft;
  box-shadow: 0 6px 16px rgba(22, 32, 58, 0.06);
}

.gn-p-overview .gn-program__top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.gn-p-overview .gn-program__top strong {
  font-size: 14px;
  font-weight: 600;
  color: $gn-ink;
}

.gn-p-overview .gn-program__desc {
  margin-top: 8px;
  font-size: 12.5px;
  line-height: 1.55;
  color: $gn-indigo;
}

.gn-p-overview .gn-program__foot {
  margin-top: 12px;
  font-size: 12px;
  color: $gn-muted;
}

.gn-p-overview .gn-program__foot i { margin-right: 6px; }


/* =========================================================
   REVIEWER ADDITIONS

   Four, and no more. Everything above is the applicant
   Overview's, so anything a reviewer needs that an applicant
   does not is gathered here where it can be seen and argued
   with.
   ========================================================= */


/* ---------- 1. the pipeline's five states ----------

   The applicant chart colours its bars by lifecycle stage.
   The reviewer pipeline needs the same treatment for a
   different five, and they follow the portal's one rule for
   colour: indigo is work in hand, green is settled, red is
   trouble, grey is stood down.
   ------------------------------------------------------- */

.gn-p-overview .gn-col__bar--pending { background: $gn-indigo-soft; }
.gn-p-overview .gn-col__bar--progress { background: $gn-indigo; }
.gn-p-overview .gn-col__bar--escalated { background: $gn-red; }
.gn-p-overview .gn-col__bar--completed { background: $gn-green; }
.gn-p-overview .gn-col__bar--declined { background: $gn-slate; }


/* ---------- 2. the score distribution ----------

   Ten columns on the same grid as the control that produced
   them, so a panel's scoring habits read against a scale the
   reviewer already has in hand. It sits where the applicant
   Overview puts its milestone bars and inherits that height,
   which is what keeps the four cards level.
   ------------------------------------------------------- */

.gn-p-overview .gn-dist {
  display: flex;
  align-items: flex-end;
  gap: 3px;
  height: 34px;
  margin-top: 16px;
}

.gn-p-overview .gn-dist__bar {
  flex: 1;
  min-height: 8%;
  border-radius: 3px;
  transition: height 0.4s ease;
}

/* the same 7 and 4 thresholds the scoring control uses, so no
   two screens disagree about what a 7 means */
.gn-p-overview .gn-dist__bar--low { background: #f3c9cd; }
.gn-p-overview .gn-dist__bar--mid { background: $gn-indigo-soft; }
.gn-p-overview .gn-dist__bar--high { background: $gn-sage; }


/* ---------- 3. the denominator ----------

   A bare 7 invites the question seven out of what. The scale
   sits on the figure's baseline at caption weight, so it
   qualifies the number without competing with it.
   ------------------------------------------------------- */

.gn-p-overview .gn-kpi__of {
  font-size: 13px;
  font-weight: 500;
  color: $gn-muted;
  align-self: flex-end;
  padding-bottom: 3px;
}


/* ---------- 4. held by another group ----------

   Visible, readable, and plainly not the reader's move. It is
   set back rather than hidden, because knowing a proposal is
   sitting with Panel B is worth something; dressing it up as
   work waiting on you is not.
   ------------------------------------------------------- */

.gn-p-overview .gn-program--muted {
  background: #fbfcfe;
  border-style: dashed;
}

.gn-p-overview .gn-program--muted .gn-program__top strong { color: $gn-ink-2; }

.gn-p-overview .gn-program--muted .gn-program__desc { color: $gn-muted; }

.gn-p-overview .gn-program--muted:hover {
  border-style: solid;
  border-color: $gn-indigo-soft;
}


/* ---------- the mismatch notice ----------

   The four widget fields are one unit. Paste three of them and
   the page renders empty cards with nothing to explain why,
   which is a worse outcome than an error.
   ------------------------------------------------------- */

.gn-p-overview .gn-stale {
  padding: 14px 18px;
  margin-bottom: 20px;
  border: 1px solid #f0ddb8;
  border-radius: 12px;
  background: #fdf6e9;
  font-size: 13px;
  line-height: 1.55;
  color: #8a6524;
}

.gn-p-overview .gn-solo { margin-bottom: 20px; }


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 1024px) {
  .gn-p-overview .gn-kpis { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .gn-p-overview .gn-row--wide { grid-template-columns: minmax(0, 1fr); }
}

@media (max-width: 900px) {
  .gn-p-overview .gn-dash { padding: 20px 16px 36px; }

  .gn-p-overview .gn-head {
    flex-direction: column;
    align-items: stretch;
  }

  .gn-p-overview .gn-head__right { flex-wrap: wrap; }

  .gn-p-overview .gn-table__head { display: none; }

  .gn-p-overview .gn-table__row {
    grid-template-columns: 1fr;
    gap: 8px;
    padding: 16px 20px;
  }

  .gn-p-overview .gn-table__row .gn-cell::before {
    content: attr(data-label);
    display: block;
    margin-bottom: 4px;
    font-size: 10.5px;
    letter-spacing: 0.6px;
    text-transform: uppercase;
    color: $gn-muted-2;
  }

  .gn-p-overview .gn-btn { width: 100%; }
}

@media (max-width: 620px) {
  .gn-p-overview .gn-kpis { grid-template-columns: minmax(0, 1fr); }
  .gn-p-overview .gn-head__title { font-size: 25px; }
  .gn-p-overview .gn-col__track { width: 100%; }
  .gn-p-overview .gn-labels span { font-size: 10.5px; }

  /* ten columns across 320px is 26px each. The distribution
     stays readable because it carries no labels of its own —
     the caption names the scale. */
  .gn-p-overview .gn-dist { gap: 2px; }
}

@media (prefers-reduced-motion: reduce) {
  .gn-p-overview .gn-dash * { transition: none; }
}

sp_widget.link:
function link(scope, element, attrs, controller) {
  function loadChartJS(cb) {
    if (typeof Chart !== 'undefined') { cb(); return; }
    var s = document.createElement('script');
    s.src = 'https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js';
    s.onload = cb;
    document.head.appendChild(s);
  }

  // Also load the Chart.js annotation plugin for deadline markers
  function loadAnnotationPlugin(cb) {
    if (typeof ChartAnnotation !== 'undefined' || !window.Chart) { cb(); return; }
    var s = document.createElement('script');
    s.src = 'https://cdn.jsdelivr.net/npm/chartjs-plugin-annotation@3.0.1/dist/chartjs-plugin-annotation.min.js';
    s.onload = cb;
    document.head.appendChild(s);
  }

  scope.$watch(function() {
    return element[0].querySelector('#rvdDonutChart');
  }, function(canvas) {
    if (!canvas) return;
    loadChartJS(function() {
      loadAnnotationPlugin(function() {
        scope.$apply(function() {
          var c = scope.$$childHead || scope.c || scope;
          if (c && c.drawCharts) c.drawCharts();
        });
      });
    });
  });
}

sp_widget.script:
(function () {

  /* =========================================================
     GATENOW · REVIEWER OVERVIEW
     Service Portal widget · Server script

     The reviewer side of the applicant Overview, built from the
     same shape of data so the two dashboards are recognisably
     one product.

     ── WHO SEES WHAT ─────────────────────────────────────────

     A review is assigned to one or more groups through the
     reviewer field, and one of them holds it at a time through
     review_group. Two different questions:

       reviewer      membership of any of these means you can
                     SEE the review
       review_group  membership of this one means it is your
                     group's turn to act

     The query is on reviewer and the turn is worked out per
     row, so a reviewer sees a proposal their panel is on even
     while a different panel holds it. Querying review_group
     alone hides it until it arrives, which is the opposite of
     what a dashboard is for.

     ── WHAT IS COUNTED, AND FROM WHAT ────────────────────────

     Every figure comes from a field on the Grant Review form:
     status, score, decision_type, review_group, reviewer,
     review_start_date, review_deadline.

     There is no completed-on column on this table. So nothing
     here claims to know when a review was finished: the
     monthly series is keyed on review_start_date and is
     labelled by when work started, not when it ended.
     ========================================================= */

  var REVIEW    = 'x_enno_gatenow_grant_review';
  var PROGRAM   = 'x_enno_gatenow_grant_program';
  var APPLICANT = 'x_enno_gatenow_service_applicants';

  var DONE     = 'Review completed';
  var DECLINED = 'Declined by Reviewer';

  var me = gs.getUserID();

  data.shape = 'reviewoverview-v1';

  function opt(name, fallback) {
    var v = options[name];
    return (v === null || v === undefined || v === '') ? fallback : v.toString();
  }

  data.links = {
    queue    : '?id=' + opt('queue_page', 'review_proposals'),
    completed: '?id=' + opt('completed_page', 'review_completed'),
    detail   : opt('detail_page', 'review_proposal_detail_page')
  };

  data.sideBar = $sp.getWidget(opt('sidebar_widget', 'review_sidebar'));


  /* ============================================================
     HELPERS
     ============================================================ */

  var MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
                'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

  function fmtDate(raw) {
    if (!raw || raw === 'null') return '';
    var d = String(raw).split(' ')[0].split('-');
    if (d.length !== 3) return String(raw).split(' ')[0];
    return parseInt(d[2], 10) + ' ' + MONTHS[parseInt(d[1], 10) - 1] + ' ' + d[0];
  }

  var now = new GlideDateTime();

  function daysFromNow(raw) {
    if (!raw) return null;
    try {
      var g = new GlideDateTime(String(raw).length === 10 ? raw + ' 00:00:00' : raw);
      return Math.round((g.getNumericValue() - now.getNumericValue()) / 86400000);
    } catch (e) { return null; }
  }

  function monthKey(raw) {
    if (!raw) return null;
    var d = String(raw).split(' ')[0].split('-');
    if (d.length !== 3) return null;
    return parseInt(d[0], 10) * 12 + (parseInt(d[1], 10) - 1);
  }

  function r1(n) { return Math.round(n * 10) / 10; }

  function pick(gr, names) {
    for (var i = 0; i < names.length; i++) {
      try {
        if (gr.isValidField(names[i])) {
          var v = gr.getValue(names[i]);
          if (v !== null && v !== undefined && v !== '') return v;
        }
      } catch (e) { /* next */ }
    }
    return '';
  }


  /* ============================================================
     WHO IS ASKING
     ============================================================ */

  var u = gs.getUser();

  data.user = {
    name    : u.getDisplayName() || gs.getUserName(),
    initials: ((u.getFirstName() || 'R').charAt(0) +
               (u.getLastName()  || '').charAt(0)).toUpperCase()
  };

  data.lastUpdated = fmtDate(now.getValue()) + ', ' +
                     now.getDisplayValue().split(' ')[1].substring(0, 5);

  var groups = [];

  try {
    var gm = new GlideRecordSecure('sys_user_grmember');
    gm.addQuery('user', me);
    gm.query();
    while (gm.next()) groups.push(gm.getValue('group'));
  } catch (e) {
    gs.warn('[ReviewerOverview] group membership unreadable: ' + e.message);
  }

  data.hasGroups = groups.length > 0;

  function mineGroup(sysId) {
    return !!sysId && groups.indexOf('' + sysId) !== -1;
  }


  /* ============================================================
     STATUS

     The five values on the form's choice list, in the order a
     review moves through them. The pipeline chart reads left to
     right in that order, which is what makes a bar chart of
     states legible rather than a bar chart of categories.
     ============================================================ */

  var PIPE = [
    { key: 'pending',  label: 'Not started',  status: 'Review pending' },
    { key: 'progress', label: 'In progress',  status: 'Review in progress' },
    { key: 'escalated',label: 'Escalated',    status: 'Escalated' },
    { key: 'completed',label: 'Completed',    status: DONE },
    { key: 'declined', label: 'Declined',     status: DECLINED }
  ];

  var STATUS_KEY = {};
  for (var pi = 0; pi < PIPE.length; pi++) STATUS_KEY[PIPE[pi].status] = PIPE[pi].key;

  function keyOf(status) { return STATUS_KEY[status] || 'progress'; }

  function isOpen(status) {
    return status !== DONE && status !== DECLINED;
  }


  /* ============================================================
     READ
     ============================================================ */

  var count = { pending: 0, progress: 0, escalated: 0, completed: 0, declined: 0 };

  var stats = {
    total: 0, turn: 0, turnOpen: 0,
    overdue: 0, thisWeek: 0, later: 0, noDeadline: 0,
    elsewhere: 0,
    scoreSum: 0, scored: 0,
    awarded: 0, rejected: 0, otherDecision: 0,
    high: 0, mid: 0, low: 0
  };

  /* one slot per point on the scale, so the distribution can be
     drawn on the same ten-point grid the scoring control uses */
  var dist = [];
  for (var z = 0; z < 10; z++) dist.push(0);

  var startedByMonth   = {};
  var completedByMonth = {};
  var deadlineByMonth  = {};

  var queue     = [];
  var elsewhere = [];
  var openList  = [];

  var programCache   = {};
  var applicantCache = {};

  function program(sysId) {
    if (!sysId) return null;
    if (programCache[sysId] !== undefined) return programCache[sysId];
    var out = null;
    try {
      var pg = new GlideRecordSecure(PROGRAM);
      if (pg.get(sysId)) {
        out = { name  : pg.getDisplayValue('program_name') || '',
                number: pg.getValue('number') || '' };
      }
    } catch (e) { /* leave null and let the row say so */ }
    programCache[sysId] = out;
    return out;
  }

  function applicant(sysId) {
    if (!sysId) return null;
    if (applicantCache[sysId] !== undefined) return applicantCache[sysId];
    var out = null;
    try {
      var ap = new GlideRecordSecure(APPLICANT);
      if (ap.get(sysId)) {
        out = { name: ((ap.getValue('first_name') || '') + ' ' +
                       (ap.getValue('last_name') || '')).trim(),
                org : ap.getValue('organization') || '' };
      }
    } catch (e) { /* as above */ }
    applicantCache[sysId] = out;
    return out;
  }

  if (groups.length) {

    var gr = new GlideRecordSecure(REVIEW);

    /* reviewer is a list of groups, so the match is CONTAINS
       per group, OR'd on the QueryCondition the first addQuery
       returned. That keeps the whole OR bracketed as one
       condition rather than leaking across the rest. */
    var hasReviewer = false;
    try { hasReviewer = gr.isValidField('reviewer'); } catch (e) {}

    if (hasReviewer) {
      var qc = gr.addQuery('reviewer', 'CONTAINS', groups[0]);
      for (var q = 1; q < groups.length; q++) {
        qc.addOrCondition('reviewer', 'CONTAINS', groups[q]);
      }
    } else {
      gr.addQuery('review_group', 'IN', groups.join(','));
      gs.info('[ReviewerOverview] no reviewer field, using review_group');
    }

    gr.orderBy('review_deadline');
    gr.query();

    while (gr.next()) {

      var status = gr.getDisplayValue('status') || 'Review pending';
      var key    = keyOf(status);
      var open   = isOpen(status);

      var holderId = gr.getValue('review_group');
      var myTurn   = mineGroup(holderId);

      var dlRaw = gr.getValue('review_deadline') || '';
      var days  = daysFromNow(dlRaw);

      /* Only work actually with one of my groups counts as late
         for me. A review past its deadline in somebody else's
         queue is their problem, and colouring it red here would
         be telling me to act on something I cannot act on. */
      var overdue  = (open && myTurn && days !== null && days < 0);
      var thisWeek = (open && myTurn && days !== null && days >= 0 && days <= 7);

      stats.total++;
      if (count[key] !== undefined) count[key]++;

      if (myTurn) stats.turn++;
      if (myTurn && open) stats.turnOpen++;
      if (!myTurn && open) stats.elsewhere++;

      if (open && myTurn) {
        if (days === null)      stats.noDeadline++;
        else if (overdue)       stats.overdue++;
        else if (thisWeek)      stats.thisWeek++;
        else                    stats.later++;
      }

      /* ---------- score ---------- */
      var scoreRaw = gr.getValue('score');
      var score    = (scoreRaw === '' || scoreRaw === null) ? null : parseFloat(scoreRaw);
      if (score === null || isNaN(score)) score = null;

      var band = 'none';
      if (score !== null) {
        /* the same 7 and 4 thresholds the scoring control uses,
           so no two screens disagree about what a 7 means */
        band = score >= 7 ? 'high' : (score >= 4 ? 'mid' : 'low');
        stats.scored++;
        stats.scoreSum += score;
        stats[band]++;
        var slot = Math.round(score) - 1;
        if (slot >= 0 && slot < 10) dist[slot]++;
      }

      /* ---------- decision ---------- */
      var decision = gr.getDisplayValue('decision_type') || '';
      if (!open && decision) {
        var dl = decision.toLowerCase();
        if (dl.indexOf('award') !== -1)       stats.awarded++;
        else if (dl.indexOf('reject') !== -1 ||
                 dl.indexOf('declin') !== -1) stats.rejected++;
        else                                  stats.otherDecision++;
      }

      /* ---------- the monthly series ----------
         Keyed on review_start_date, because that is the only
         date on this table that says when work happened. */
      var startRaw = pick(gr, ['review_start_date']);
      var sk = monthKey(startRaw);
      if (sk !== null) {
        startedByMonth[sk] = (startedByMonth[sk] || 0) + 1;
        if (key === 'completed') completedByMonth[sk] = (completedByMonth[sk] || 0) + 1;
      }

      var dk = monthKey(dlRaw);
      if (dk !== null) {
        if (!deadlineByMonth[dk]) {
          deadlineByMonth[dk] = { done: 0, progress: 0, pending: 0 };
        }
        if (!open)                     deadlineByMonth[dk].done++;
        else if (key === 'pending')    deadlineByMonth[dk].pending++;
        else                           deadlineByMonth[dk].progress++;
      }

      /* ---------- the rows the page lists ---------- */
      var pgm = program(gr.getValue('program'));
      var apl = applicant(gr.getValue('applicant'));

      var dueText, dueTone;
      if (!dlRaw)          { dueText = 'No deadline'; dueTone = 'grey'; }
      else if (!open)      { dueText = fmtDate(dlRaw); dueTone = 'grey'; }
      else if (!myTurn)    { dueText = fmtDate(dlRaw); dueTone = 'grey'; }
      else if (days < 0)   { var n = Math.abs(days);
                             dueText = n + (n === 1 ? ' day overdue' : ' days overdue');
                             dueTone = 'red'; }
      else if (days === 0) { dueText = 'Due today'; dueTone = 'amber'; }
      else if (days <= 7)  { dueText = 'Due in ' + days + (days === 1 ? ' day' : ' days');
                             dueTone = 'amber'; }
      else                 { dueText = fmtDate(dlRaw); dueTone = 'green'; }

      var row = {
        sys_id   : gr.getUniqueValue(),
        number   : gr.getValue('number') || '',
        applicant: apl ? apl.name : '',
        org      : apl ? apl.org : '',
        program  : pgm ? pgm.name : '',
        status   : status,
        key      : key,
        holder   : gr.getDisplayValue('review_group') || '',
        myTurn   : myTurn,
        score    : score,
        scoreText: score === null ? '' : r1(score) + '',
        band     : band,
        started  : fmtDate(startRaw),
        deadline : fmtDate(dlRaw),
        dueText  : dueText,
        dueTone  : dueTone,
        days     : days,
        url      : '?id=' + data.links.detail + '&sys_id=' + gr.getUniqueValue()
      };

      if (open && myTurn && queue.length < 8) queue.push(row);
      if (open && !myTurn && elsewhere.length < 5) elsewhere.push(row);

      /* every open review of mine, for the deadline panel's
         list — capped, because a dashboard list that runs past
         a screen has stopped being a summary */
      if (open && myTurn && openList.length < 6) {
        openList.push({
          name   : row.number + (row.applicant ? ' · ' + row.applicant : ''),
          tone   : dueTone === 'red' ? 'red' : (dueTone === 'amber' ? 'amber' : 'green'),
          /* how far into the review window this one is. Without
             a start date there is nothing to measure against,
             so it shows as just begun rather than as complete. */
          percent: (function () {
            var s = daysFromNow(startRaw);
            if (s === null || days === null) return 8;
            var span = days - s;
            if (!span || span <= 0) return 92;
            var gone = 0 - s;
            var pc = Math.round((gone / span) * 100);
            return Math.max(4, Math.min(100, pc));
          })(),
          due    : dueText
        });
      }
    }
  }


  /* ============================================================
     THE KPI CARDS
     ============================================================ */

  /* the last twelve months, ending on this one */
  var nowKey = monthKey(now.getValue());
  var series = [];
  var running = 0;

  for (var m = nowKey - 11; m <= nowKey; m++) {
    running += (startedByMonth[m] || 0);
    series.push({
      label    : MONTHS[((m % 12) + 12) % 12],
      started  : startedByMonth[m] || 0,
      completed: completedByMonth[m] || 0,
      cumulative: running
    });
  }

  var avg = stats.scored ? r1(stats.scoreSum / stats.scored) : null;

  data.kpi = {

    assigned: {
      total     : stats.total,
      turn      : stats.turnOpen,
      pending   : count.pending,
      progress  : count.progress,
      completed : count.completed,
      /* the sparkline's series, cumulative so the line only
         ever climbs — a cumulative line answers "how much have
         we taken on", which is the question a volume figure
         raises */
      cumulative: (function () {
        var out = [];
        for (var i = 0; i < series.length; i++) out.push(series[i].cumulative);
        return out;
      })()
    },

    waiting: {
      total   : stats.turnOpen,
      overdue : stats.overdue,
      thisWeek: stats.thisWeek,
      later   : stats.later + stats.noDeadline
    },

    completed: {
      total   : count.completed,
      pct     : stats.total ? Math.round((count.completed / stats.total) * 100) : 0,
      awarded : stats.awarded,
      rejected: stats.rejected,
      other   : stats.otherDecision,
      perMonth: (function () {
        var out = [];
        for (var i = 0; i < series.length; i++) out.push(series[i].completed);
        return out;
      })()
    },

    score: {
      avg     : avg === null ? '—' : ('' + avg),
      hasAvg  : avg !== null,
      scored  : stats.scored,
      unscored: count.completed - stats.scored > 0 ? count.completed - stats.scored : 0,
      dist    : dist
    }
  };


  /* ============================================================
     THE PIPELINE

     Counted in lifecycle order rather than by size. A bar chart
     of states that sorts itself by count stops being a pipeline
     and becomes a league table.
     ============================================================ */

  data.pipeline = [];
  for (var pj = 0; pj < PIPE.length; pj++) {
    data.pipeline.push({
      key  : PIPE[pj].key,
      label: PIPE[pj].label,
      count: count[PIPE[pj].key] || 0
    });
  }


  /* ============================================================
     DEADLINE HEALTH
     ============================================================ */

  data.health = {
    red   : stats.overdue,
    yellow: stats.thisWeek,
    green : stats.later,
    none  : stats.noDeadline,
    total : stats.turnOpen,
    list  : openList
  };


  /* ============================================================
     DEADLINE LOAD BY MONTH

     Grouped rather than stacked. Stacked answers "how many fall
     in this month", which the axis already says; grouped
     answers "how much of it is still open", which is the
     question a reviewer actually has.
     ============================================================ */

  var dks = [];
  for (var dkk in deadlineByMonth) {
    if (deadlineByMonth.hasOwnProperty(dkk)) dks.push(parseInt(dkk, 10));
  }
  dks.sort(function (a, b) { return a - b; });

  data.monthly = { months: [], totals: { done: 0, progress: 0, pending: 0 }, none: 0 };

  if (dks.length) {

    var lo = dks[0];
    var hi = dks[dks.length - 1];

    /* this month is always in frame. A deadline chart that
       stops last month says nothing about this week. */
    if (nowKey !== null) {
      if (nowKey < lo) lo = nowKey;
      if (nowKey > hi) hi = nowKey;
    }

    /* six columns is as many as the card holds before the
       month labels start colliding */
    if (hi - lo > 5) lo = hi - 5;

    for (var mm = lo; mm <= hi; mm++) {
      var b = deadlineByMonth[mm] || { done: 0, progress: 0, pending: 0 };
      data.monthly.months.push({
        label   : MONTHS[((mm % 12) + 12) % 12],
        done    : b.done,
        progress: b.progress,
        pending : b.pending
      });
      data.monthly.totals.done     += b.done;
      data.monthly.totals.progress += b.progress;
      data.monthly.totals.pending  += b.pending;
    }
  }

  data.monthly.none = stats.total -
    (data.monthly.totals.done + data.monthly.totals.progress + data.monthly.totals.pending);
  if (data.monthly.none < 0) data.monthly.none = 0;


  /* ============================================================
     SCORES BY BAND
     ============================================================ */

  data.bands = {
    total: stats.scored,
    avg  : avg === null ? '—' : ('' + avg),
    items: [
      { label: 'Strong, 7 to 10',   count: stats.high, tone: 'green' },
      { label: 'Moderate, 4 to 6',  count: stats.mid,  tone: 'indigo' },
      { label: 'Weak, 1 to 3',      count: stats.low,  tone: 'amber' },
      { label: 'Completed, not scored',
        count: data.kpi.score.unscored, tone: 'soft' }
    ],
    footnote: stats.scored
      ? stats.scored + ' of ' + count.completed + ' completed reviews carry a score'
      : 'No scores recorded yet'
  };


  /* ============================================================
     THE LISTS
     ============================================================ */

  data.queue     = queue;
  data.elsewhere = elsewhere;

  data.counts = count;

})();
